def filter_primes(numbers):
    """
    Returns a new list containing only the prime numbers from the input list.
    - Numbers less than 2 (including 0, 1, and negatives) are not prime.
    - Duplicates are kept in the original order.
    """
    result = []
    for num in numbers:
        if num < 2:
            continue
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            result.append(num)
    return result
