def remove_duplicates(s: str) -> str:
    """
    Removes all duplicate characters from the input string s.
    Only the first occurrence of each character is kept.
    Returns an empty string if s is empty.
    """
    if not s:
        return ""

    result = []
    char_index = {}

    for char in s:
        if char in char_index:
            # Skip the duplicate
            pass
        else:
            # Add the first occurrence
            char_index[char] = 1
            result.append(char)

    return "".join(result)
