def removeDuplicates(s: str) -> str:
    """
    Removes all duplicate words from the input string.
    Returns the sentence with only the first occurrence of each word kept.
    """
    result = []
    current_word = ""

    for char in s:
        if char.isspace():
            # If we are currently processing a word, append it to the result
            if current_word:
                result.append(current_word)
            current_word = ""
        else:
            current_word += char

    # Append the last word if it was processed
    if current_word:
        result.append(current_word)

    return "".join(result)
