def manage_participants(queries):
    """
    Manages a list of unique participants with their scores.
    Supports: Add, Delete, and Count min_score max_score.
    """
    # Dictionary to store participant info: {name: (score, index)}
    # We use a list to store the data and an index to track position for efficient deletion
    participants = {}

    for query in queries:
        if query == "Add":
            name, score = query.split()
            if name in participants:
                participants[name] = (participants[name][1], participants[name][2] + 1)
            else:
                participants[name] = (score, len(participants))
        elif query == "Delete":
            name = query.split()[-1]
            if name in participants:
                del participants[name]
        elif query == "Count":
            min_score, max_score = query.split()
            count = 0
            for name, (score, _) in participants.items():
                if min_score <= score <= max_score:
                    count += 1
            return count
        else:
            # Ignore other queries
            pass

    return []
